// Payload node — builds enriched prompt for AI Agent
const wb = $('Webhook').first().json.body;
const userName = ((wb.user_name || '') + ' ' + (wb.user_surname || '')).trim();
const currentMsg = $input.first().json.message || wb.message || '';
const history = wb.conversation_history || [];

let historyStr = '';
if (history.length > 0) {
  historyStr = '\n=== HISTORIQUE DE CONVERSATION ===\n' +
    history.map(m => 'User: ' + m.role_user + '\nAstroBot: ' + m.role_assistant).join('\n\n') +
    '\n=== FIN HISTORIQUE ===\n\n';
}

const message = 'Utilisateur: ' + userName + '\n' + historyStr + 'Message actuel: ' + currentMsg;
return [{ json: { message } }];
